<?php
namespace App\Models; use App\Models\Concerns\Auditable; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\SoftDeletes;
class ContractTemplateVersion extends Model { use Auditable, SoftDeletes; protected $fillable=['contract_template_id','country_id','language_id','version_number','content','status','is_current','created_by']; protected $casts=['is_current'=>'boolean']; public function template(){return $this->belongsTo(ContractTemplate::class,'contract_template_id');} public function country(){return $this->belongsTo(Country::class);} public function language(){return $this->belongsTo(Language::class);} public function creator(){return $this->belongsTo(User::class,'created_by');} }
